import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } } from '@/primitives';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Container for the node
  const node = new Group();

  // Plane geometry – size matches typical backdrop (7x6 units)
  const geometry = new PlaneGeometry(7, 6);
  const material = new MeshBasicNodeMaterial({
    map: null,
    transparent: true,
    depthWrite: false,
  });

  const plane = new Mesh(geometry, material);
  // Apply rotation and scale from spec (adapter will set position)
  plane.rotation.set(0, 0, 0);
  plane.scale.set(1, 1, 1);
  node.add(plane);

  // Load texture asynchronously; assign when ready
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
      loadedTexture = tex;
    });
  }

  // No primitives for this node, but keep a place for future ones
  const primitiveInstances = [];

  // Event handlers placeholder
  node.userData.handlers = {};

  // Cleanup routine
  node.userData.cleanup = () => {
    // Dispose primitives if any were added
    primitiveInstances.forEach((p) => {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    });
    // Kill any GSAP timelines (none in this node)
    // (If timelines were added, store them and kill here)

    // Dispose material, geometry, and texture
    if (material) material.dispose();
    if (geometry) geometry.dispose();
    if (loadedTexture) loadedTexture.dispose();

    // Remove from parent if still attached
    if (node.parent) node.parent.remove(node);
  };

  return node;
}
